window.kbPageData["views/entry/k-554ebafbe8d1bfe3"] = {"key":"entry/k-554ebafbe8d1bfe3","state":{"route":"entry/k-554ebafbe8d1bfe3"},"node":{"id":"k-554ebafbe8d1bfe3","mode":"k","title":"习近平党建思想","type":"概念与词义","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["party"],"主类":["概念与词义"],"出处性质":["机构注释"],"学科":["政治理论"],"来源主题":["党政制度与理论"],"资料类别":["非时政"]},"directorySummary":"1.习近平党建思想\n2026 年 6 月 15 日，全国党建工作座谈会在京召开，中共中央政治局常委、中央书\n记处书记蔡奇出席会议并讲话，中共中央政治局常委、中央纪律检查委员会书记李希\n出席会议。会议认为，党的十八大以来，以习近平同志为核心的党中央围绕建设什么\n样的长期执政的马克思主义政党、怎样建设长…","sources":[{"id":"9e85630e3edf73c6","label":"习近平党建思想","topic":"党政制度与理论","category":"非时政","text":"1.习近平党建思想\n2026 年 6 月 15 日，全国党建工作座谈会在京召开，中共中央政治局常委、中央书\n记处书记蔡奇出席会议并讲话，中共中央政治局常委、中央纪律检查委员会书记李希\n出席会议。会议认为，党的十八大以来，以习近平同志为核心的党中央围绕建设什么\n样的长期执政的马克思主义政党、怎样建设长期执政的马克思主义政党的重大时代课\n题，提出一系列新理念新思想新战略，形成习近平党建思想。\n习近平党建思想内涵要义可以概括为“十四个坚持”：\n①坚持党的领导是中国特色社会主义最本质的特征；\n②坚持党中央集中统一领导是党的领导的最高原则；\n③坚持全面从严治党是新时代党的建设的战略方针；\n④坚持不忘初心、牢记使命是党的宗旨立场和价值取向；\n⑤坚持以党的政治建设为统领是新时代党的建设的根本要求；\n⑥坚持用党的创新理论凝心铸魂是党的思想建设的根本任务；\n⑦坚持锤炼坚强党性是党员、干部的终身课题；\n⑧坚持健全上下贯通、执行有力的组织体系是党的优势所在、力量所在；\n⑨坚持建设堪当民族复兴重任的高素质干部队伍是关系党和国家事业的关键性问\n题；\n⑩坚持推进作风建设常态化长效化是保持党同人民群众血肉联系的有效途径；\n⑪坚持用严明的纪律管全党治全党是全面从严治党的治本之策；\n⑫坚持一体推进不敢腐不能腐不想腐是全面从严治党的重要方略和反腐败斗争的\n基本方针；\n⑬坚持制度治党、依规治党是全面从严治党的长远和根本之策；\n⑭坚持落实管党治党政治责任是全面从严治党需要牢牢牵住的“牛鼻子”。","source":{"doc":"41195a191a57c1c36332","first":8,"last":8,"page":8,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"party","title":"党的建设与自我革命"}],"units":{"k-554ebafbe8d1bfe3":[]}};
